pub type RestrictedGeometryFuture = Pin<
    Box<
        dyn Future<Output = Result<RestrictedGeometryOutput, RestrictedGeometryError>>
            + Send
            + 'static,
    >,
>;

/// The only Python/worker-facing K003 geometry capability.
pub trait RestrictedGeometryPort: Send + Sync + 'static {
    fn build_compile_render(
        &self,
        input: RestrictedGeometryInput,
        cancellation: CancellationToken,
    ) -> RestrictedGeometryFuture;
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum RestrictedGeometryErrorKind {
    InvalidInput,
    Unsupported,
    Cancelled,
    Timeout,
    Execution,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct RestrictedGeometryError {
    pub code: String,
    pub kind: RestrictedGeometryErrorKind,
    pub message: String,
    pub recoverable: bool,
}

impl RestrictedGeometryError {
    pub fn execution(code: impl Into<String>, message: impl Into<String>) -> Self {
        Self {
            code: code.into(),
            kind: RestrictedGeometryErrorKind::Execution,
            message: message.into(),
            recoverable: false,
        }
    }

    pub fn cancelled() -> Self {
        Self {
            code: "RESTRICTED_GEOMETRY_CANCELLED".into(),
            kind: RestrictedGeometryErrorKind::Cancelled,
            message: "Restricted geometry work was cancelled.".into(),
            recoverable: true,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct RestrictedQualityProfile {
    pub profile_id: String,
    pub runtime_manifest_version: String,
    pub max_triangle_count: u32,
    pub render_width: u16,
    pub render_height: u16,
    pub require_closed_manifold: bool,
    pub require_surface_provenance: bool,
}

impl RestrictedQualityProfile {
    fn for_presentation(value: &str) -> Result<Self, NativeToolFailure> {
        match value {
            "quick_sketch" => Ok(Self {
                profile_id: "interactive_preview".into(),
                runtime_manifest_version: RESTRICTED_GEOMETRY_RUNTIME_MANIFEST_VERSION.into(),
                max_triangle_count: 7_000,
                render_width: 320,
                render_height: 320,
                require_closed_manifold: true,
                require_surface_provenance: true,
            }),
            "showcase" => Ok(Self {
                profile_id: "production_concept".into(),
                runtime_manifest_version: RESTRICTED_GEOMETRY_RUNTIME_MANIFEST_VERSION.into(),
                max_triangle_count: 150_000,
                // The exact convergence views are also consumed by the
                // reference-comparison Provider. 128px thumbnails erased the
                // fasteners, identifier, emissive trims and roughness cues the
                // micro-detail gate is meant to judge. Keep the workbench GLB
                // lightweight, but render the eight audited views at the same
                // reviewed 640px production benchmark used by C111.
                render_width: 640,
                render_height: 640,
                require_closed_manifold: true,
                require_surface_provenance: true,
            }),
            _ => Err(NativeToolFailure::schema(
                "PRESENTATION_PROFILE_INVALID",
                "Presentation profile is outside the code-owned quality profiles.",
            )),
        }
    }

    fn validate(&self) -> Result<(), NativeToolFailure> {
        if !matches!(
            self.profile_id.as_str(),
            "interactive_preview" | "production_concept"
        ) || self.runtime_manifest_version != RESTRICTED_GEOMETRY_RUNTIME_MANIFEST_VERSION
            || !(100..=150_000).contains(&self.max_triangle_count)
            || !(64..=2048).contains(&self.render_width)
            || !(64..=2048).contains(&self.render_height)
            || !self.require_closed_manifold
            || !self.require_surface_provenance
        {
            return Err(NativeToolFailure::schema(
                "RESTRICTED_QUALITY_PROFILE_INVALID",
                "Restricted geometry quality profile is not code-owned or bounded.",
            ));
        }
        Ok(())
    }
}

/// Strict worker request.  It intentionally has no execution or product ID.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct RestrictedGeometryInput {
    pub schema_version: String,
    pub shape_program: Value,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub profile_sketch: Option<Value>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub section_set: Option<Value>,
    /// Bounded visual-only texture programs. They carry no lifecycle or write
    /// capability; Rust validates the active immutable Skill before this
    /// restricted compiler input is constructed.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub surface_adornment_programs: Vec<SurfaceAdornmentProgram>,
    /// A private-construction Rust seal around one `SurfaceLayerProgram@1`
    /// lowering. Python receives only this reviewed DTO and cannot provide a
    /// second authoring language or select a different A005 program list.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub surface_layer_input: Option<RestrictedSurfaceLayerInput>,
    /// U004+ category-open source path: multiple independently sealed Design
    /// Surfaces, one per real material zone. Legacy callers keep using the
    /// singular field above so historical C111/A005 fixtures remain stable.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub surface_layer_inputs: Vec<RestrictedSurfaceLayerInput>,
    /// Transient Rust-sealed reference pixels. This field is never part of a
    /// Provider tool schema or preview/version persistence; only the native
    /// executor may attach values after it has read sealed evidence.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub reference_uv_evidence_bakes: Vec<ReferenceCameraUvRasterBake>,
    /// Selects deterministic audit views only. It never changes geometry or
    /// the workbench's single WebGL renderer.
    #[serde(default)]
    pub render_view_profile: RestrictedRenderViewProfile,
    pub quality_profile: RestrictedQualityProfile,
}

#[derive(Debug, Clone, Copy, Default, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum RestrictedRenderViewProfile {
    #[default]
    WorkbenchFour,
    ConvergenceEight,
    TurntableEight,
}

impl RestrictedRenderViewProfile {
    fn required_views(self) -> BTreeSet<&'static str> {
        match self {
            Self::WorkbenchFour => WORKBENCH_REQUIRED_VIEWS.into_iter().collect(),
            Self::ConvergenceEight => CONVERGENCE_REQUIRED_VIEWS.into_iter().collect(),
            Self::TurntableEight => TURNTABLE_REQUIRED_VIEWS.into_iter().collect(),
        }
    }
}

/// Exact Rust-owned retained-surface payload for the RestrictedGeometryPort.
/// Its fields are private so normal callers can only construct it by lowering
/// a validated `SurfaceLayerProgram` through `from_program`.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct RestrictedSurfaceLayerInput {
    schema_version: String,
    lowering: SurfaceLayerLowering,
    lowering_sha256: String,
}

impl RestrictedSurfaceLayerInput {
    pub fn from_program(program: &SurfaceLayerProgram) -> Result<Self, RestrictedGeometryError> {
        let lowering = program
            .lower()
            .map_err(|error| restricted_input_error(error.to_string()))?;
        // The new retained PBR compiler currently shares the existing A005
        // base-material channel. A Design Surface with no reviewed relief may
        // remain stored/previewed at the Core layer, but it cannot cross this
        // v1 executor boundary until its base-material contract is explicit.
        if lowering.adornments().is_empty() {
            return Err(restricted_input_error(
                "Restricted surface lowering requires at least one reviewed A005 normal-relief layer.",
            ));
        }
        let lowering_sha256 = restricted_surface_lowering_sha256(&lowering)?;
        let sealed = Self {
            schema_version: "RestrictedSurfaceLayerInput@1".into(),
            lowering,
            lowering_sha256,
        };
        sealed.validate()?;
        Ok(sealed)
    }

    pub fn lowering(&self) -> &SurfaceLayerLowering {
        &self.lowering
    }

    pub fn lowering_sha256(&self) -> &str {
        &self.lowering_sha256
    }

    pub fn validate(&self) -> Result<(), RestrictedGeometryError> {
        if self.schema_version != "RestrictedSurfaceLayerInput@1" {
            return Err(restricted_input_error(
                "Restricted surface lowering schema version is unsupported.",
            ));
        }
        self.lowering
            .validate()
            .map_err(|error| restricted_input_error(error.to_string()))?;
        if self.lowering.adornments().is_empty()
            || !is_sha256(&self.lowering_sha256)
            || self.lowering_sha256 != restricted_surface_lowering_sha256(&self.lowering)?
        {
            return Err(restricted_input_error(
                "Restricted surface lowering is not an exact Rust-owned sealed payload.",
            ));
        }
        Ok(())
    }
}

fn restricted_surface_lowering_sha256(
    lowering: &SurfaceLayerLowering,
) -> Result<String, RestrictedGeometryError> {
    let value = serde_json::to_value(lowering).map_err(|_| {
        restricted_input_error("Restricted surface lowering could not be serialized.")
    })?;
    Ok(sha256_hex(canonical_json(&value).as_bytes()))
}

impl RestrictedGeometryInput {
    pub fn validate(&self) -> Result<(), RestrictedGeometryError> {
        if self.schema_version != RESTRICTED_GEOMETRY_INPUT_SCHEMA_VERSION {
            return Err(restricted_input_error(
                "Restricted geometry input version is unsupported.",
            ));
        }
        let serialized = serde_json::to_value(self).map_err(|_| {
            restricted_input_error("Restricted geometry input could not be inspected.")
        })?;
        reject_forbidden_json(&serialized)
            .map_err(|failure| restricted_input_error(failure.message))?;
        reject_high_level_geometry_context(&serialized)
            .map_err(|failure| restricted_input_error(failure.message))?;
        self.quality_profile
            .validate()
            .map_err(|failure| restricted_input_error(failure.message))?;
        validate_shape_program_value(&self.shape_program)
            .map_err(|failure| restricted_input_error(failure.message))?;
        let program_budget = self
            .shape_program
            .get("triangle_budget")
            .and_then(Value::as_u64)
            .unwrap_or(u64::MAX);
        if program_budget
            > u64::from(
                self.quality_profile
                    .max_triangle_count
                    .min(MAX_SHAPE_PROGRAM_TRIANGLE_BUDGET),
            )
        {
            return Err(restricted_input_error(
                "ShapeProgram triangle budget exceeds its code-owned quality profile.",
            ));
        }
        if let Some(profile) = self.profile_sketch.as_ref() {
            validate_profile_sketch_value(profile)
                .map_err(|failure| restricted_input_error(failure.message))?;
        }
        if let Some(section_set) = self.section_set.as_ref() {
            validate_section_set_value(section_set)
                .map_err(|failure| restricted_input_error(failure.message))?;
        }
        if self.surface_adornment_programs.len() > 32 {
            return Err(restricted_input_error(
                "Restricted geometry accepts at most thirty-two visual adornments.",
            ));
        }
        let mut adornment_target_zones = BTreeSet::new();
        for program in &self.surface_adornment_programs {
            program
                .validate()
                .map_err(|failure| restricted_input_error(failure.to_string()))?;
            if !adornment_target_zones.insert(program.target_zone_id.as_str()) {
                return Err(restricted_input_error(
                    "Restricted geometry accepts only one visual adornment per Material Zone.",
                ));
            }
        }
        if self.surface_layer_input.is_some() && !self.surface_layer_inputs.is_empty() {
            return Err(restricted_input_error(
                "Restricted geometry cannot mix legacy and multi-zone retained surface inputs.",
            ));
        }
        if self.surface_layer_inputs.len() > 8 {
            return Err(restricted_input_error(
                "Restricted geometry accepts at most eight sealed retained surface inputs.",
            ));
        }
        let surface_inputs = self
            .surface_layer_input
            .iter()
            .chain(self.surface_layer_inputs.iter());
        let mut retained_zone_ids = BTreeSet::new();
        for surface_layer_input in surface_inputs {
            surface_layer_input.validate()?;
            let lowered = surface_layer_input.lowering().adornments();
            if !lowered.iter().all(|expected| {
                self.surface_adornment_programs
                    .iter()
                    .any(|supplied| supplied == expected)
            }) {
                return Err(restricted_input_error(
                    "Restricted surface layers must retain every exact A005 instruction emitted by their Rust lowering.",
                ));
            }
            let layer_zones = lowered
                .iter()
                .map(|program| program.target_zone_id.as_str())
                .collect::<BTreeSet<_>>();
            for zone_id in &layer_zones {
                if !retained_zone_ids.insert(*zone_id) {
                    return Err(restricted_input_error(
                        "Restricted geometry retained surface inputs cannot share a Material Zone.",
                    ));
                }
            }
            if self.surface_adornment_programs.iter().any(|program| {
                layer_zones.contains(program.target_zone_id.as_str())
                    && !lowered.iter().any(|expected| expected == program)
            }) {
                return Err(restricted_input_error(
                    "A retained Design Surface must be the only visual program for its Material Zone.",
                ));
            }
        }
        if self.reference_uv_evidence_bakes.len() > 8 {
            return Err(restricted_input_error(
                "Restricted geometry accepts at most eight Rust-sealed reference UV bakes.",
            ));
        }
        let mut evidence_zones = BTreeMap::<&str, BTreeSet<String>>::new();
        let mut evidence_zone_schemas = BTreeMap::<&str, BTreeSet<String>>::new();
        for bake in &self.reference_uv_evidence_bakes {
            bake.validate()
                .map_err(|error| restricted_input_error(error.to_string()))?;
            if !retained_zone_ids.contains(bake.target_material_zone_id.as_str()) {
                return Err(restricted_input_error(
                    "Reference UV evidence must target a Rust-sealed retained material zone.",
                ));
            }
            let identity = format!("{}:{}", bake.source_evidence_id, bake.camera_hypothesis_id);
            let identities = evidence_zones
                .entry(bake.target_material_zone_id.as_str())
                .or_default();
            if !identities.insert(identity) {
                return Err(restricted_input_error(
                    "Reference UV fusion cannot repeat one sealed evidence/camera identity.",
                ));
            }
            if identities.len() > 2 {
                return Err(restricted_input_error(
                    "Reference UV fusion accepts at most two sealed views per Material Zone.",
                ));
            }
            evidence_zone_schemas
                .entry(bake.target_material_zone_id.as_str())
                .or_default()
                .insert(bake.schema_version.clone());
        }
        for (zone_id, schemas) in evidence_zone_schemas {
            let count = evidence_zones
                .get(zone_id)
                .map(BTreeSet::len)
                .unwrap_or_default();
            if count > 1
                && (schemas.len() != 1 || !schemas.contains("ReferenceCameraUvRasterBake@2"))
            {
                return Err(restricted_input_error(
                    "Only camera-space ReferenceCameraUvRasterBake@2 may fuse multiple views for one Material Zone.",
                ));
            }
        }
        validate_geometry_companion_binding(
            &self.shape_program,
            self.profile_sketch.as_ref(),
            self.section_set.as_ref(),
        )?;
        Ok(())
    }

    /// Attaches a reviewed Design Surface atomically. The A005 list is copied
    /// only from the same sealed lowering; callers cannot pair arbitrary
    /// retained layers with unrelated texture-bake programs.
    pub fn with_surface_layer_program(
        mut self,
        program: &SurfaceLayerProgram,
    ) -> Result<Self, RestrictedGeometryError> {
        if self.surface_layer_input.is_some() || !self.surface_layer_inputs.is_empty() {
            return Err(restricted_input_error(
                "Restricted geometry accepts at most one sealed Design Surface.",
            ));
        }
        let surface_layer_input = RestrictedSurfaceLayerInput::from_program(program)?;
        let layer_zones = surface_layer_input
            .lowering()
            .adornments()
            .iter()
            .map(|adornment| adornment.target_zone_id.as_str())
            .collect::<BTreeSet<_>>();
        if self.surface_adornment_programs.iter().any(|adornment| {
            layer_zones.contains(adornment.target_zone_id.as_str())
                && !surface_layer_input
                    .lowering()
                    .adornments()
                    .iter()
                    .any(|expected| expected == adornment)
        }) {
            return Err(restricted_input_error(
                "A retained Design Surface cannot share its Material Zone with an independent adornment.",
            ));
        }
        for adornment in surface_layer_input.lowering().adornments() {
            if !self.surface_adornment_programs.contains(adornment) {
                self.surface_adornment_programs.push(adornment.clone());
            }
        }
        self.surface_layer_input = Some(surface_layer_input);
        self.validate()?;
        Ok(self)
    }

    /// Attaches a bounded set of independently sealed material-zone layers.
    /// This path is only used by the Rust-derived UAS@2 appearance compiler.
    pub fn with_surface_layer_programs(
        mut self,
        programs: &[SurfaceLayerProgram],
    ) -> Result<Self, RestrictedGeometryError> {
        if self.surface_layer_input.is_some()
            || !self.surface_layer_inputs.is_empty()
            || programs.is_empty()
            || programs.len() > 8
        {
            return Err(restricted_input_error(
                "Restricted geometry requires one to eight multi-zone retained surface programs on an otherwise empty input.",
            ));
        }
        let inputs = programs
            .iter()
            .map(RestrictedSurfaceLayerInput::from_program)
            .collect::<Result<Vec<_>, _>>()?;
        let mut zones = BTreeSet::new();
        for input in &inputs {
            for adornment in input.lowering().adornments() {
                if !zones.insert(adornment.target_zone_id.as_str()) {
                    return Err(restricted_input_error(
                        "Multi-zone retained surface programs cannot target the same Material Zone.",
                    ));
                }
                if !self.surface_adornment_programs.contains(adornment) {
                    self.surface_adornment_programs.push(adornment.clone());
                }
            }
        }
        self.surface_layer_inputs = inputs;
        self.validate()?;
        Ok(self)
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct RestrictedGeometryReadback {
    pub runtime_manifest_version: String,
    pub artifact_profile_id: String,
    pub shape_program_sha256: String,
    pub glb_sha256: String,
    pub glb_byte_size: u64,
    pub triangle_count: u32,
    pub bounds_mm: [f64; 3],
    pub mesh_count: u32,
    pub primitive_count: u32,
    pub material_count: u32,
    pub closed_manifold: bool,
    pub surface_provenance_present: bool,
    /// Canonical digest of the exact `GeometryCompileReadback@2` value
    /// accepted by the Rust↔Python boundary.  It lets the V003 evidence
    /// profile cite real compiler facts without retaining the full report in
    /// the transient Product Tool state.
    pub compile_readback_sha256: String,
    /// Bounded summaries copied only after the bridge validates the worker's
    /// material-zone and visual-texture evidence.
    pub material_zone_count: u32,
    pub visual_texture_set_count: u32,
    pub visual_texture_map_count: u32,
    pub visual_texture_provenance_verified: bool,
    /// Hash/count-only reference projection facts extracted from the exact
    /// worker GLB. The native UAS path later adds source/request lineage and
    /// the final compiled-artifact identity before persistence.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub reference_appearance_projection_receipts: Vec<ReferenceAppearanceProjectionReadback>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct ReferenceAppearanceProjectionReadback {
    #[serde(alias = "schema_version")]
    pub worker_schema_version: String,
    pub algorithm_id: String,
    pub algorithm_version: String,
    pub projection_id: String,
    pub projection_sha256: String,
    pub source_evidence_id: String,
    pub source_image_sha256: String,
    pub camera_hypothesis_id: String,
    pub camera_provenance_sha256: String,
    pub target_material_zone_id: String,
    pub base_color_texture_id: String,
    pub base_color_sha256: String,
    pub base_color_byte_size: u64,
    pub unobserved_texel_mask_id: String,
    pub unobserved_texel_mask_sha256: String,
    pub unobserved_texel_mask_byte_size: u64,
    pub observed_texel_count: u64,
    pub unobserved_texel_count: u64,
    pub fusion_count: u8,
    pub raster_triangle_count: u32,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub world_to_clip_sha256: Option<String>,
    #[serde(default)]
    pub source_evidence_ids: Vec<String>,
    #[serde(default)]
    pub source_image_sha256s: Vec<String>,
    #[serde(default)]
    pub camera_hypothesis_ids: Vec<String>,
    #[serde(default)]
    pub camera_provenance_sha256s: Vec<String>,
    #[serde(default)]
    pub world_to_clip_sha256s: Vec<String>,
    /// Digest of the exact worker receipt object, before this bounded bridge
    /// DTO was extracted. It prevents a later source binding from proving a
    /// different receipt than the one read from the GLB.
    #[serde(skip, default)]
    pub worker_receipt_sha256: String,
}

impl ReferenceAppearanceProjectionReadback {
    pub fn validate(&self) -> Result<(), RestrictedGeometryError> {
        let stable = |value: &str| {
            !value.is_empty()
                && value.len() <= 200
                && value.chars().all(|character| {
                    character.is_ascii_alphanumeric() || matches!(character, '_' | '-')
                })
        };
        if !matches!(
            self.worker_schema_version.as_str(),
            "ReferenceCameraUvRasterBakeReceipt@2" | "ReferenceCameraUvRasterFusionReceipt@3"
        ) || self.algorithm_id != "forgecad.reference_camera_uv_raster"
            || self.algorithm_version != "1"
            || !is_sha256(&self.projection_sha256)
            || !is_sha256(&self.source_image_sha256)
            || !is_sha256(&self.camera_provenance_sha256)
            || !is_sha256(&self.base_color_sha256)
            || !is_sha256(&self.unobserved_texel_mask_sha256)
            || !is_sha256(&self.worker_receipt_sha256)
            || !stable(&self.projection_id)
            || !stable(&self.source_evidence_id)
            || !stable(&self.camera_hypothesis_id)
            || !stable(&self.target_material_zone_id)
            || !stable(&self.base_color_texture_id)
            || !stable(&self.unobserved_texel_mask_id)
            || self.base_color_byte_size == 0
            || self.unobserved_texel_mask_byte_size == 0
            || self.observed_texel_count == 0
            || self.unobserved_texel_count == 0
            || self.fusion_count == 0
            || self.fusion_count > 2
            || self.raster_triangle_count == 0
        {
            return Err(restricted_geometry_invalid_response());
        }
        if self.worker_schema_version == "ReferenceCameraUvRasterBakeReceipt@2" {
            if self.fusion_count != 1
                || self
                    .world_to_clip_sha256
                    .as_ref()
                    .is_none_or(|hash| !is_sha256(hash))
                || !self.source_evidence_ids.is_empty()
                || !self.source_image_sha256s.is_empty()
                || !self.camera_hypothesis_ids.is_empty()
                || !self.camera_provenance_sha256s.is_empty()
                || !self.world_to_clip_sha256s.is_empty()
            {
                return Err(restricted_geometry_invalid_response());
            }
        } else if self.fusion_count != 2
            || self.world_to_clip_sha256.is_some()
            || self.source_evidence_ids.len() != 2
            || self.source_image_sha256s.len() != 2
            || self.camera_hypothesis_ids.len() != 2
            || self.camera_provenance_sha256s.len() != 2
            || self.world_to_clip_sha256s.len() != 2
            || self.source_evidence_ids[0] != self.source_evidence_id
            || self.source_image_sha256s[0] != self.source_image_sha256
            || self.camera_hypothesis_ids[0] != self.camera_hypothesis_id
            || self.camera_provenance_sha256s[0] != self.camera_provenance_sha256
            || self.source_evidence_ids[0] == self.source_evidence_ids[1]
            || self
                .source_image_sha256s
                .iter()
                .any(|hash| !is_sha256(hash))
            || self
                .camera_provenance_sha256s
                .iter()
                .any(|hash| !is_sha256(hash))
            || self
                .world_to_clip_sha256s
                .iter()
                .any(|hash| !is_sha256(hash))
            || self.source_evidence_ids.iter().any(|value| !stable(value))
            || self
                .camera_hypothesis_ids
                .iter()
                .any(|value| !stable(value))
        {
            return Err(restricted_geometry_invalid_response());
        }
        Ok(())
    }
}

fn restricted_geometry_invalid_response() -> RestrictedGeometryError {
    RestrictedGeometryError::execution(
        "RESTRICTED_GEOMETRY_RESPONSE_INVALID",
        "Restricted geometry returned bytes or readback outside the frozen contract.",
    )
}

