    impl ActiveDesignSnapshotReader for SnapshotReaderFixture {
        fn read_active_design_snapshot(
            &self,
            project_id: &str,
        ) -> Result<Option<Value>, ProductToolPortError> {
            Ok(Some(json!({
                "schema_version": "ActiveDesignSnapshot@1",
                "project_id": project_id,
                "active_design": {
                    "source": "agent_asset",
                    "project_id": project_id,
                    "asset_version_id": "assetver_current",
                    "assembly_graph_id": "assembly_current"
                },
                "revision": 7
            })))
        }

        fn read_reference_evidence_content(
            &self,
            project_id: &str,
            evidence_id: &str,
        ) -> Result<Option<ReferenceEvidenceContent>, ProductToolPortError> {
            let context = pv006c_multimodal_context();
            let Some(evidence) = context
                .evidence()
                .iter()
                .find(|item| item.project_id == project_id && item.evidence_id == evidence_id)
                .cloned()
            else {
                return Ok(None);
            };
            Ok(Some(ReferenceEvidenceContent {
                evidence,
                bytes: Arc::from(PV006C_REFERENCE_BYTES),
            }))
        }
    }

    #[derive(Clone)]
    struct U004ReferenceImageReader {
        evidence: ReferenceEvidence,
        bytes: Arc<[u8]>,
    }

    impl ActiveDesignSnapshotReader for U004ReferenceImageReader {
        fn read_active_design_snapshot(
            &self,
            _project_id: &str,
        ) -> Result<Option<Value>, ProductToolPortError> {
            Ok(None)
        }

        fn read_reference_evidence_content(
            &self,
            project_id: &str,
            evidence_id: &str,
        ) -> Result<Option<ReferenceEvidenceContent>, ProductToolPortError> {
            if project_id != self.evidence.project_id || evidence_id != self.evidence.evidence_id {
                return Ok(None);
            }
            Ok(Some(ReferenceEvidenceContent {
                evidence: self.evidence.clone(),
                bytes: self.bytes.clone(),
            }))
        }
    }

    const PV006C_REFERENCE_BYTES: &[u8] = b"pv006c-reference-image";

    #[derive(Clone, Default)]
    struct RepairingReferenceComparisonProvider {
        calls: Arc<AtomicUsize>,
    }

    impl VisualReferenceComparisonProviderPort for RepairingReferenceComparisonProvider {
        fn compare(
            &self,
            _request: VisualReferenceComparisonProviderRequest,
            _cancellation: CancellationToken,
        ) -> crate::VisualReferenceComparisonProviderFuture {
            let call = self.calls.fetch_add(1, Ordering::SeqCst);
            Box::pin(async move {
                let assessment = |claim_id: &str,
                                  level_reason: &str,
                                  mismatch: bool|
                 -> VisualReferenceClaimAssessment {
                    VisualReferenceClaimAssessment {
                        claim_id: claim_id.into(),
                        outcome: if mismatch {
                            forgecad_core::VisualReferenceMatchOutcome::Partial
                        } else {
                            forgecad_core::VisualReferenceMatchOutcome::Matched
                        },
                        similarity_bps: if mismatch { 5_000 } else { 8_800 },
                        confidence_bps: 9_000,
                        source_evidence_ids: vec!["refevid_pv006c_native".into()],
                        candidate_view_ids: vec!["iso".into(), "front".into()],
                        reason: level_reason.into(),
                    }
                };
                Ok(crate::VisualReferenceComparisonProviderOutput {
                    provider_id: "vision_comparison_fixture".into(),
                    model_id: "vision_comparison_fixture".into(),
                    provider_response_sha256: if call == 0 {
                        "d".repeat(64)
                    } else {
                        "e".repeat(64)
                    },
                    analyzed_at: "2026-07-26T12:02:00Z".into(),
                    assessments: vec![
                        assessment(
                            "vclaim_native_macro",
                            "Silhouette needs one bounded repair.",
                            call == 0,
                        ),
                        assessment("vclaim_native_meso", "Panel structure matches.", false),
                        assessment("vclaim_native_micro", "Surface finish matches.", false),
                    ],
                    network_call_made: false,
                    budget_evidence: None,
                    e005_visual_patch_proposal: None,
                })
            })
        }
    }

    #[test]
    fn native_executor_reads_snapshot_only_from_attached_rust_port() {
        let executor = executor_with(
            Arc::new(SuccessGeometryPort::default()),
            NativeProductToolExecutorConfig::default(),
        );
        assert_eq!(
            executor.read_active_design_snapshot("project_arm").unwrap(),
            None
        );
        executor
            .attach_active_snapshot_reader(Arc::new(SnapshotReaderFixture))
            .unwrap();
        let snapshot = executor
            .read_active_design_snapshot("project_arm")
            .unwrap()
            .unwrap();
        assert_eq!(
            snapshot["active_design"]["asset_version_id"],
            "assetver_current"
        );
        assert!(executor
            .attach_active_snapshot_reader(Arc::new(SnapshotReaderFixture))
            .is_err());
    }

    fn request(
        registry: &ProductToolRegistry,
        name: &str,
        arguments: Value,
        call_id: &str,
        execution_id: &str,
        turn_id: &str,
        cancellation_id: &str,
        cancellation_token: &str,
    ) -> ProductToolExecutionRequest {
        registry
            .build_execution_request(
                turn_id,
                &ProviderToolCall {
                    call_id: call_id.into(),
                    name: name.into(),
                    arguments,
                },
                execution_id,
                cancellation_id,
                cancellation_token,
            )
            .unwrap_or_else(|error| panic!("{name} request invalid: {error:?}"))
    }

    fn standard_request(
        registry: &ProductToolRegistry,
        name: &str,
        arguments: Value,
        call_id: &str,
    ) -> ProductToolExecutionRequest {
        request(
            registry,
            name,
            arguments,
            call_id,
            "execution_native",
            "turn_native",
            "cancel_native",
            "cancel_token_native",
        )
    }

